from collections import deque
def solve(I):
    H=len(I);W=len(I[0])
    # seed color: color whose cells form a complete rectangle outline (bbox perimeter == all its cells)
    from collections import Counter
    cnt=Counter(v for row in I for v in row)
    tc=None
    for c,n in cnt.items():
        if c==0: continue
        pts=[(i,j) for i in range(H) for j in range(W) if I[i][j]==c]
        r1=min(p[0] for p in pts);r2=max(p[0] for p in pts);c1=min(p[1] for p in pts);c2=max(p[1] for p in pts)
        perim={(i,j) for i in range(r1,r2+1) for j in range(c1,c2+1) if i in(r1,r2) or j in(c1,c2)}
        if set(pts)==perim:
            tc=c; break
    # zero regions
    zc=[];seen=set();D4=[(-1,0),(1,0),(0,-1),(0,1)]
    for p in [(i,j) for i in range(H) for j in range(W) if I[i][j]==0]:
        if p in seen: continue
        st=[p];seen.add(p);comp=[]
        while st:
            q=st.pop();comp.append(q)
            for dr,dc in D4:
                n=(q[0]+dr,q[1]+dc)
                if 0<=n[0]<H and 0<=n[1]<W and I[n[0]][n[1]]==0 and n not in seen:
                    seen.add(n);st.append(n)
        zc.append(comp)
    out=[row[:] for row in I]
    for comp in zc:
        if len(comp)<2: continue
        rr=[p[0] for p in comp];cc=[p[1] for p in comp]
        r1,r2,c1,c2=min(rr),max(rr),min(cc),max(cc)
        R_r1,R_r2,R_c1,R_c2=max(0,r1-1),min(H-1,r2+1),max(0,c1-1),min(W-1,c2+1)
        perim={(i,j) for i in range(R_r1,R_r2+1) for j in range(R_c1,R_c2+1) if i in(R_r1,R_r2) or j in(R_c1,R_c2)}
        # exclude if perim contains a zero belonging to a different region
        zeroset={p for reg in zc for p in reg if p!=comp}
        if any(p in zeroset for p in perim): continue
        for i,j in perim:
            out[i][j]=tc
    return out
